def gen(r):
    cids=[bytes([r.randrange(256)]) for _ in range(r.choice([1,2,3]))]
    cids=[bytes([0xaa]),bytes([0xbb]),bytes([0xcc])][:r.choice([1,2,3])]
    lim=dict(connection=r.choice([5,15,1000,2**62-1]),stream=r.choice([5,15,100,2**62-1]),
             bidi=r.choice([1,2,3,8]),uni=r.choice([1,2,3,8]),cids=r.choice([2,3,4]))
    loc=dict(bidi=r.choice([0,1,2,3]),uni=r.choice([0,1,2,3]),cids=[c.hex() for c in cids])
    peer=dict(cid=bytes([0xcc]).hex(),token='00'*16)
    seeds=dict(I=r.choice([None,0,5]),H=r.choice([None,0,3]),A=r.choice([None,None,0,7,100]))
    events=[]
    pn={'I':0,'H':0,'A':0}
    for _ in range(r.randrange(0,8)):
        if r.random()<0.25:
            ks=r.sample(['I','H','A'],r.randrange(0,4))
            events.append({'keys':ks})
            continue
        nlev=r.randrange(1,3)
        wire=b''
        auth=[]
        for _ in range(nlev):
            lvl=r.choice(['I','H','A'])
            frames=b''.join(rnd_frame(r,lvl,None) for _ in range(r.randrange(0,4)))
            if r.random()<0.2: frames=frames+bytes(r.randrange(256) for _ in range(r.randrange(1,4)))
            width=r.choice([1,1,2,4])
            pn[lvl]=pn[lvl]+r.choice([0,1,1,2,5])
            phase=r.choice([0,1])
            cid=r.choice(cids) if lvl=='A' else bytes([r.randrange(256)])
            if lvl=='A' and r.random()<0.15: cid=bytes([0x99])
            e=envelope(lvl,pn[lvl],frames,cid=cid,scid=bytes([0xbb]),token=b'' if r.random()<0.5 else b'1234',width=width,phase=phase)
            if r.random()<0.1: e=e[:-r.randrange(1,3)] if len(e)>3 else e
            wire+=e
            auth.append(r.choice([None,0,0,0,1,1,2,3]))
        if r.random()<0.1: wire=bytes(r.randrange(256) for _ in range(r.randrange(0,10)))
        events.append({'datagram':{'wire':wire.hex(),'auth':auth}})
    return dict(limits=lim,local=loc,peer=peer,received=seeds,events=events)

